			g.fillRect(x, y, 16, 16);
			g.setColor(border);
			g.drawRect(x, y, 16, 16);
		}

		/* @Override */
		public int getIconWidth() {
			return 18;
		}

		/* @Override */
		public int getIconHeight() {
			return 18;
		}
	}

	/* @Override */
	public ActionContext getActionContext(MouseEvent e) {
		return null;
	}

	class GroupingStrategy
{	public static readonly GroupingStrategy REF = new();
	public static readonly GroupingStrategy SAME_COLORS = new();
	public static readonly GroupingStrategy BIN_8 = new();
	public static readonly GroupingStrategy BIN_64 = new();
	public static readonly GroupingStrategy BIN_512 = new();


		private string name;

		GroupingStrategy(string name) {
			this.name = name;
		}

		/* @Override */
		public string toString() {
			return name;
		}
	}

	private class ColorNode : GTreeNode {
		protected Color color;
		protected Icon icon;
		private string name;
		protected string displayText;

		ColorNode(Color color) : this(color, "")
    {
		}

		ColorNode(Color color, string namePrefix) {
			this.name = namePrefix + getColorString(color);
			this.color = color is GColor ? new Color(color.getRGB()) : color;
			this.icon = new SwatchIcon(color);
		}

		/* @Override */
		public string getName() {
			return name;
		}

		/* @Override */
		public string getDisplayText() {
			if (displayText == null) {
				displayText = name;
				int childCount = getChildCount();
				if (childCount > 0) {
					int leafCount = getLeafCount();
					displayText = name + "  (" + childCount + ", " + leafCount + ")";
				}
			}
			return displayText;
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return icon;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

		public Color getColor() {
			return color;
		}

		protected string getColorString(Color c) {
			string colorName = WebColors.toString(c, false);

			string webColorName = WebColors.toWebColorName(c);
			if (webColorName != null) {
				colorName += " (" + webColorName + ")";
			}
			return colorName;
		}

		public void sort(ColorSorter sorter) {
			if (getChildCount() == 0) {
				return;
			}
			List<GTreeNode> children = new(getChildren());

			foreach (GTreeNode node in children) {
				((ColorNode) node).sort(sorter);
			}
			sortChildren(children, sorter);
			setChildren(children);
		}

		protected void sortChildren(List<GTreeNode> nodes, ColorSorter sorter) {
			Collections.sort(nodes,
				(a, b) => sorter.compare(((ColorNode) a).getColor(), ((ColorNode) b).getColor()));
		}
	}

	private class SameColorGroupNode : ColorNode {
		SameColorGroupNode(Color color) : base(color)
    {
