		public string getName() {
			return "Colors";
		}

		/* @Override */
		public string getDisplayText() {
			return "Colors (" + uniqueColors + " unique colors)";
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}
	}

